        "ESCALATE" => Verdict::Escalate(if reason.is_empty() {
            "escalated for human review".to_string()
        } else {
            reason
        }),
        // Anything unrecognised fails closed to a human.
        _ => Verdict::Escalate("unparseable moderation reply".to_string()),
    }
}

/// Percent-encode every byte outside the RFC 3986 unreserved set, so that
/// untrusted question text cannot alter the URL's structure (no extra
/// query parameters, no fragment, no host change).
fn encode_query_component(s: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char);
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0F) as usize] as char);
            }
        }
    }
    out
}

/// Enrichment lookup. Its result does not feed the moderation decision, so
/// the node's output is independent of it. A transport failure comes back as
/// a value via `fetch` and is ignored; a refused host traps at the boundary.
fn enrich(question: &str) {
    let url = format!("{}{}", ENRICH_BASE, encode_query_component(question));
    let _ = crate::aap::caps::http_client::fetch(&url);
}

impl Guest for Node {
    fn run(query: CustomerQuery) -> ModerationResult {
        // Enrichment is performed on every call. Its outcome is discarded.
        enrich(&query.question);

        // Defensive check of the node's precondition; a violating input
        // is routed to a human rather than moderated on trust.
        if query.question.chars().count() > MAX_QUESTION_CHARS {
